// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import "./interfaces/IERC20.sol";
import "./GameFactory.sol";

/**
 * @title MatchMind - Football Prediction dApp on Chiliz Chain
 * @dev Main contract that combines GameFactory with additional utilities
 * @author MatchMind Team
 */
contract MatchMind {
    address public immutable owner;
    address public immutable chzToken;
    address public immutable stakingContract;
    address public immutable validator;
    
    GameFactory public factory;
    
    event FactoryDeployed(address indexed factoryAddress, uint256 timestamp);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }
    
    constructor(
        address _owner,
        address _chzToken,
        address _stakingContract,
        address _validator
    ) {
        owner = _owner;
        chzToken = _chzToken;
        stakingContract = _stakingContract;
        validator = _validator;
        
        // Deploy the factory
        factory = new GameFactory(owner, chzToken, stakingContract, validator);
        emit FactoryDeployed(address(factory), block.timestamp);
    }
    
    /**
     * @dev Creates a new game through the factory
     */
    function createGame() external onlyOwner returns (uint256) {
        return factory.createGame();
    }
    
    /**
     * @dev Starts a match through the factory
     */
    function startMatch(uint256 gameId) external onlyOwner {
        factory.startMatch(gameId);
    }
    
    /**
     * @dev Ends a match through the factory
     */
    function endMatch(uint256 gameId) external onlyOwner {
        factory.endMatch(gameId);
    }
    
    /**
     * @dev Distributes yield through the factory
     */
    function distributeYield(uint256 gameId, address[] calldata rankings) external onlyOwner {
        factory.distributeYield(gameId, rankings);
    }
    
    /**
     * @dev Emergency function to recover stuck tokens
     */
    function emergencyRecover(address token, uint256 amount) external onlyOwner {
        require(IERC20(token).transfer(owner, amount), "Transfer failed");
    }
}

